    // Uses the same provider rail, cards and picker as the text model editor.
    internal sealed class ImageGenerationSettings:Grid,IDisposable
    {
        readonly PetWindow pet;readonly List<ImageGenerationProvider> draft;
        readonly ListBox providers=new ListBox{Name="ImageProviderPicker",BorderThickness=new Thickness(0),Background=Brushes.Transparent,MinHeight=76,MaxHeight=340,HorizontalContentAlignment=HorizontalAlignment.Stretch,Margin=new Thickness(0,12,0,10)};
        readonly TextBox name=Ui.Field(""),address=Ui.Field(""),model=Ui.Field(""),proxy=Ui.Field(""),timeout=Ui.Field("300");
        readonly PasswordBox key=new PasswordBox{MinHeight=38,Padding=new Thickness(10,7,10,7),BorderBrush=Ui.Line,Background=ThemeManager.FieldSurface};
        readonly ComboBox size=DefaultChoices(new[]{"1024x1024","1536x1024","1024x1536"}),quality=DefaultChoices(new[]{"auto","low","medium","high"});
        readonly ComboBox presets=new ComboBox{Name="ImageServicePreset",MinHeight=38,Padding=new Thickness(8)},protocol=new ComboBox{Name="ImageServiceProtocol",MinHeight=38,Padding=new Thickness(8),SelectedValuePath="Tag"};
        readonly CheckBox useProxy,edits;readonly TextBlock notice,endpoint,empty;readonly Border railCard,detailCard;readonly Button remove;
        readonly StackPanel result=new StackPanel();readonly Expander connection;
        ImageGenerationProvider selected;CancellationTokenSource cancellation;string imageJobId;bool loading,disposed;string saved;
        internal static ComboBox DefaultChoices(string[] choices){return new ComboBox{IsEditable=true,MinHeight=38,Padding=new Thickness(8),ItemsSource=new[]{"服务默认"}.Concat(choices).ToArray(),Text="服务默认"};}
        internal static string Optional(ComboBox box){return box.Text.Trim()=="服务默认"?"":box.Text.Trim();}
        internal ImageGenerationSettings(PetWindow owner)
        {
            pet=owner;pet.Settings.EnsureImageProviders();draft=pet.Settings.ImageProviders.Select(p=>p.Copy()).ToList();Name="ImageGenerationSettings";
            ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(138)});ColumnDefinitions.Add(new ColumnDefinition());RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});
            var rail=new StackPanel();var title=Ui.Text("服务商",15);title.FontWeight=FontWeights.SemiBold;rail.Children.Add(title);rail.Children.Add(Ui.Text("独立地址与密钥",10,Ui.Muted));
            ScrollViewer.SetHorizontalScrollBarVisibility(providers,ScrollBarVisibility.Disabled);rail.Children.Add(providers);
            var add=Ui.Button("＋ 新增");add.Name="AddImageProvider";add.FontSize=11;add.Margin=new Thickness(0,0,0,7);add.Padding=new Thickness(6);add.Click+=delegate{ChooseProvider();};rail.Children.Add(add);
            remove=Ui.Button("移除服务商");remove.Name="RemoveImageProvider";remove.FontSize=11;remove.Margin=new Thickness(0);remove.Padding=new Thickness(6);remove.Click+=async delegate{if(selected==null)return;var deleting=selected;int count=pet.ImageTasks.List().Count(t=>t.ProviderId==deleting.Id&&!t.IsTerminal);if(!ConfirmRemoveProvider(count))return;await pet.ImageTasks.CancelProviderAsync(deleting.Id);int index=draft.IndexOf(deleting);draft.Remove(deleting);Reload(draft.Count==0?null:draft[Math.Min(index,draft.Count-1)].Id);};rail.Children.Add(remove);rail.Children.Add(Ui.Text("保存后使用当前服务商与模型。",10,Ui.Muted));
            railCard=TextProviderEditor.Glass(rail,10);railCard.Name="ImageProviderRail";railCard.Margin=new Thickness(0,0,12,0);railCard.VerticalAlignment=VerticalAlignment.Top;Children.Add(railCard);
            var detail=new StackPanel();name.Name="ImageProviderName";address.Name="ImageProviderAddress";model.Name="ImageProviderModel";key.Name="ImageProviderKey";timeout.Name="ImageProviderTimeout";size.Name="ImageProviderSize";quality.Name="ImageProviderQuality";
            Ui.Label(detail,"服务商名称",name);
            var fields=new StackPanel();var connectionTitle=Ui.Text("连接设置",17);connectionTitle.FontWeight=FontWeights.SemiBold;fields.Children.Add(connectionTitle);fields.Children.Add(Ui.Text("选择常用服务，或接入自己的兼容接口。",12,Ui.Muted));
            presets.ItemsSource=ImageServicePresets.All;presets.SelectionChanged+=delegate{if(!loading&&presets.SelectedItem is ImageServicePreset)ApplyPreset((ImageServicePreset)presets.SelectedItem);};
            foreach(string id in ImageServicePresets.Protocols)protocol.Items.Add(new ComboBoxItem{Tag=id,Content=ProtocolName(id)});
            protocol.SelectionChanged+=delegate{if(loading)return;var item=protocol.SelectedItem as ComboBoxItem;RefreshParameters(item==null?"openai":item.Tag as string??"openai");size.Text=quality.Text="服务默认";};
            fields.Children.Add(Pair("服务预设",presets,"接口协议",protocol));Ui.Label(fields,"服务地址（保留 /v1 等前缀）",address);Ui.Label(fields,"API 密钥",key);
            useProxy=Ui.Toggle("使用代理连接",false,v=>proxy.IsEnabled=v);fields.Children.Add(useProxy);Ui.Label(fields,"代理地址（仅开启代理时使用）",proxy);Ui.Label(fields,"超时（秒）",timeout);
            endpoint=Ui.Text("",10,Ui.Muted);endpoint.TextWrapping=TextWrapping.NoWrap;endpoint.TextTrimming=TextTrimming.CharacterEllipsis;var summary=new StackPanel();var caption=Ui.Text("连接设置",12);caption.FontWeight=FontWeights.SemiBold;summary.Children.Add(caption);summary.Children.Add(endpoint);
            connection=new Expander{Name="ImageConnectionDetails",Header=summary,Content=fields,IsExpanded=true,Padding=new Thickness(0,4,0,4),Margin=new Thickness(0,14,0,12)};detail.Children.Add(connection);
            var modelHeading=Ui.Text("生成模型",16);modelHeading.FontWeight=FontWeights.SemiBold;detail.Children.Add(modelHeading);detail.Children.Add(Ui.Text("填写账号可用的模型 ID；兼容网关的模型名称可以自定义。",11,Ui.Muted));Ui.Label(detail,"模型 ID",model);
            detail.Children.Add(Pair("默认尺寸",size,"默认质量",quality));edits=Ui.Toggle("此服务支持参考图编辑",false,delegate{});detail.Children.Add(edits);
            var actions=new WrapPanel{Margin=new Thickness(0,12,0,0)};var save=Ui.Button("保存并使用",true);save.Name="SaveImageProvider";save.Click+=delegate{Save();};actions.Children.Add(save);
            var test=Ui.Button("测试生成");test.Name="TestImageGeneration";test.Click+=async delegate{if(cancellation!=null||!Save())return;var c=new CancellationTokenSource();cancellation=c;notice.Text="正在生成测试图片…";test.IsEnabled=false;try{var handle=await pet.ImageTasks.EnqueueAsync(new ImageGenerationTaskSubmission(Guid.NewGuid().ToString("N"),new ImageGenerationRequest{Provider=selected.Copy(),Prompt="A simple blue ceramic cup on a clean white background, soft natural light.",Size=selected.Size,Quality=selected.Quality,SessionId="settings-test",Persistent=pet.Settings.SaveChatHistory},new ImageTaskOrigin{Source=ImageGenerationSource.SettingsTest}) { BeforeStart = id => { imageJobId=id; return Task.FromResult(0); } },CancellationToken.None);var image=await handle.Completion;if(!disposed){result.Children.Clear();result.Children.Add(new GeneratedImageCard(pet,Window.GetWindow(this),image));notice.Text="测试生成成功，图片已加入图库。";}}catch(OperationCanceledException){notice.Text="测试已取消。";}catch(Exception e){notice.Text=e is ApiException||e is InvalidOperationException||e is TimeoutException||e is IOException?e.Message:"测试生成失败，请检查服务和配置。";}finally{if(ReferenceEquals(cancellation,c))cancellation=null;c.Dispose();test.IsEnabled=true;}};actions.Children.Add(test);
            var stop=Ui.Button("取消测试");stop.Click+=delegate{if(imageJobId!=null)pet.ImageTasks.CancelAsync(imageJobId);};actions.Children.Add(stop);detail.Children.Add(actions);notice=Ui.Text("",11,Ui.Muted);notice.Name="ImageProviderNotice";notice.Margin=new Thickness(0,10,0,0);detail.Children.Add(notice);detail.Children.Add(result);
            detailCard=TextProviderEditor.Glass(detail,14);detailCard.Name="ImageProviderDetails";Grid.SetColumn(detailCard,1);Children.Add(detailCard);empty=Ui.Text("尚未添加服务商\n点击左侧「＋ 新增」选择服务商并填写连接。",13,Ui.Muted);empty.Name="ImageProvidersEmpty";empty.Margin=new Thickness(20,30,12,20);Grid.SetColumn(empty,1);Children.Add(empty);
            providers.SelectionChanged+=delegate{if(loading)return;var item=providers.SelectedItem as ListBoxItem;if(item==null)return;try{Capture();selected=(ImageGenerationProvider)item.Tag;Load();}catch(Exception e){notice.Text=e.Message;}};
            name.TextChanged+=delegate{if(loading||selected==null)return;selected.Name=name.Text;RefreshProviderRows();};
            string keyOrigin="";key.PasswordChanged+=delegate{keyOrigin=address.Text;};address.TextChanged+=delegate{if(loading)return;if(key.Password.Length>0&&!ServicePresets.SameOrigin(keyOrigin,address.Text))key.Clear();endpoint.Text=address.Text;};
            SizeChanged+=delegate{bool narrow=ActualWidth<480;ColumnDefinitions[0].Width=narrow?new GridLength(1,GridUnitType.Star):new GridLength(138);ColumnDefinitions[1].Width=narrow?new GridLength(0):new GridLength(1,GridUnitType.Star);Grid.SetColumnSpan(railCard,narrow?2:1);railCard.Margin=narrow?new Thickness(0,0,0,12):new Thickness(0,0,12,0);Grid.SetColumn(detailCard,narrow?0:1);Grid.SetRow(detailCard,narrow?1:0);Grid.SetColumnSpan(detailCard,narrow?2:1);Grid.SetColumn(empty,narrow?0:1);Grid.SetRow(empty,narrow?1:0);Grid.SetColumnSpan(empty,narrow?2:1);providers.MaxHeight=narrow?120:340;};
            Reload(pet.Settings.ActiveImageProviderId);saved=Signature();
        }
        static Grid Pair(string leftLabel,UIElement left,string rightLabel,UIElement right)
        {var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition());grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var a=new StackPanel{Margin=new Thickness(0,0,8,0)};Ui.Label(a,leftLabel,left);grid.Children.Add(a);var b=new StackPanel{Margin=new Thickness(8,0,0,0)};Ui.Label(b,rightLabel,right);Grid.SetColumn(b,1);grid.Children.Add(b);grid.SizeChanged+=delegate{bool narrow=grid.ActualWidth<340;grid.ColumnDefinitions[1].Width=narrow?new GridLength(0):new GridLength(1,GridUnitType.Star);Grid.SetColumn(b,narrow?0:1);Grid.SetRow(b,narrow?1:0);a.Margin=narrow?new Thickness(0):new Thickness(0,0,8,0);b.Margin=narrow?new Thickness(0):new Thickness(8,0,0,0);};return grid;}
        void ChooseProvider(){try{Capture();if(draft.Count>=32)throw new InvalidOperationException("最多添加 32 个生图服务。");var picker=new ProviderPickerWindow(Window.GetWindow(this),"image");if(picker.ShowDialog()==true)AddProvider(picker.SelectedImageProvider);}catch(Exception e){notice.Text=e is InvalidOperationException?e.Message:"无法添加生图服务，请重试。";}}
        void AddProvider(ImageServicePreset preset){if(preset==null)return;var next=preset.CreateProvider();draft.Add(next);Reload(next.Id);notice.Text=preset.Notes;connection.IsExpanded=true;}
        void ApplyPreset(ImageServicePreset preset){if(selected==null)return;if(!ServicePresets.SameOrigin(address.Text,preset.BaseUrl))key.Clear();name.Text=preset.Name;address.Text=preset.BaseUrl;model.Text=preset.Model;protocol.SelectedValue=preset.Protocol;edits.IsChecked=preset.SupportsEdits;RefreshParameters(preset.Protocol);size.Text=quality.Text="服务默认";notice.Text=preset.Notes;}
        void Reload(string id){selected=draft.FirstOrDefault(p=>p.Id==id)??draft.FirstOrDefault();RefreshProviderRows();Load();}
        void RefreshProviderRows(){bool previous=loading;loading=true;providers.Items.Clear();foreach(var p in draft){var row=new DockPanel();var logo=ProviderLogo.Create(p.Connection.BaseUrl,p.Name,22);logo.Margin=new Thickness(0,0,7,0);DockPanel.SetDock(logo,Dock.Left);row.Children.Add(logo);var label=Ui.Text(String.IsNullOrWhiteSpace(p.Name)?"未命名服务":p.Name,11);label.TextWrapping=TextWrapping.NoWrap;label.TextTrimming=TextTrimming.CharacterEllipsis;label.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(label);var item=new ListBoxItem{Style=TextProviderEditor.ProviderItemStyle,Tag=p,Content=row,ToolTip=p.Name,Padding=new Thickness(6,9,6,9),Margin=new Thickness(0,0,0,4)};providers.Items.Add(item);if(ReferenceEquals(p,selected))item.IsSelected=true;}loading=previous;}
        static string ProtocolName(string id){switch(id){case "gemini":return "Gemini 原生图片";case "doubao":return "豆包 Seedream";case "minimax":return "MiniMax 原生图片";case "qwen":return "千问 Images";case "grok":return "Grok Images";default:return "OpenAI Images 兼容";}}
        void RefreshParameters(string id){size.ItemsSource=new[]{"服务默认"}.Concat(ImageServicePresets.Sizes(id)).ToArray();quality.ItemsSource=new[]{"服务默认"}.Concat(ImageServicePresets.Qualities(id)).ToArray();}
        void Load(){loading=true;bool exists=selected!=null;detailCard.Visibility=exists?Visibility.Visible:Visibility.Collapsed;empty.Visibility=exists?Visibility.Collapsed:Visibility.Visible;remove.IsEnabled=exists;presets.SelectedItem=null;if(exists){protocol.SelectedValue=selected.Protocol;RefreshParameters(selected.Protocol);name.Text=selected.Name;address.Text=selected.Connection.BaseUrl;endpoint.Text=address.Text;model.Text=selected.Connection.Model;key.Password=selected.Connection.ApiKey;timeout.Text=selected.TimeoutSeconds.ToString();size.Text=String.IsNullOrEmpty(selected.Size)?"服务默认":selected.Size;quality.Text=String.IsNullOrEmpty(selected.Quality)?"服务默认":selected.Quality;useProxy.IsChecked=selected.Connection.UseProxy;proxy.Text=selected.Connection.ProxyAddress;proxy.IsEnabled=useProxy.IsChecked==true;edits.IsChecked=selected.SupportsEdits;connection.IsExpanded=String.IsNullOrEmpty(address.Text)||String.IsNullOrEmpty(model.Text);}notice.Text="选择“服务默认”时省略对应参数；测试会实际生成一张图片。";loading=false;}
        void Capture(){if(loading||selected==null)return;int seconds;if(!Int32.TryParse(timeout.Text,out seconds)||seconds<1||seconds>3600)throw new InvalidOperationException("超时需为 1–3600 秒。");selected.Name=name.Text.Trim();selected.Protocol=protocol.SelectedValue as string??"openai";selected.Connection.BaseUrl=address.Text.Trim();selected.Connection.ApiKey=key.Password;selected.Connection.Model=model.Text.Trim();selected.Connection.UseProxy=useProxy.IsChecked==true;selected.Connection.ProxyAddress=proxy.Text.Trim();selected.TimeoutSeconds=seconds;selected.Size=Optional(size);selected.Quality=Optional(quality);selected.SupportsEdits=edits.IsChecked==true;selected.Normalize();}
        string Signature(){return String.Join("|",draft.Select(p=>p.Id+":"+p.Name+":"+p.Protocol+":"+p.Connection.BaseUrl+":"+p.Connection.Model+":"+p.Connection.ApiKey+":"+p.Connection.UseProxy+":"+p.Connection.ProxyAddress+":"+p.Size+":"+p.Quality+":"+p.TimeoutSeconds+":"+p.SupportsEdits))+"/"+(selected==null?"":selected.Id);}
        internal bool HasUnsavedChanges{get{try{Capture();return Signature()!=saved;}catch(InvalidOperationException){return true;}}}
        internal bool Save(){try{Capture();pet.Settings.ImageProviders=draft.Select(p=>p.Copy()).ToList();pet.Settings.ActiveImageProviderId=selected==null?"":selected.Id;pet.Settings.EnsureImageProviders();pet.SaveSettings();if(!String.IsNullOrEmpty(pet.Store.Warning))throw new InvalidOperationException("图片配置保存失败，请检查目录权限。");saved=Signature();RefreshProviderRows();notice.Text="已保存并使用所选生图服务。";return true;}catch(Exception e){notice.Text=e is InvalidOperationException||e is ApiException||e is TimeoutException||e is IOException?e.Message:"配置保存失败，请检查地址和密钥。";return false;}}
        bool ConfirmRemoveProvider(int count)
        {
            var dialog=new Window{Owner=Window.GetWindow(this),SizeToContent=SizeToContent.Height,Name="RemoveImageProviderDialog"};Ui.Window(dialog,"移除生图服务",480,210);
            var body=new StackPanel{Margin=new Thickness(24)};body.Children.Add(Ui.Text("移除生图服务",21));var text=Ui.Text("此服务有 "+count+" 个未完成图片任务。确认取消这些任务并移除服务？",14,Ui.Muted);text.TextWrapping=TextWrapping.Wrap;body.Children.Add(text);
            var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,18,0,0)};var cancel=Ui.Button("取消");cancel.IsCancel=true;cancel.Click+=delegate{dialog.DialogResult=false;};var remove=Ui.Button("取消任务并移除");remove.Name="ConfirmRemoveImageProvider";remove.Click+=delegate{dialog.DialogResult=true;};actions.Children.Add(cancel);actions.Children.Add(remove);body.Children.Add(actions);DialogUi.Apply(dialog,body);return dialog.ShowDialog()==true;
        }
        public void Dispose(){disposed=true;}
    }
}
